(6413502, 951260, 96751, '<td valign="top">LOL!!!</td>', 'LOL!!!', '2011-05-14 13:59:34.000000', NULL, 1),
(6413504, 949157, 96751, '<td valign="top">Freak. Me. Out. Like it''s parachuting down. INCOMING!!!!!!!!!!<br/> <br/>I do believe that''s a black widow...?</td>', 'Freak. Me. Out. Like it''s parachuting down. INCOMING!!!!!!!!!! I do believe that''s a black widow...?', '2011-05-14 14:01:18.000000', NULL, 1),
(6413505, 950724, 96751, '<td valign="top">Lovely.  Can''t decided if the double reflection makes or breaks this shot.  But I like the vintage treatment.</td>', 'Lovely.  Can''t decided if the double reflection makes or breaks this shot.  But I like the vintage treatment.', '2011-05-14 14:02:06.000000', NULL, 1),
(6413506, 951076, 96751, '<td valign="top">Man o MAN, what a job!  Love the shot.</td>', 'Man o MAN, what a job!  Love the shot.', '2011-05-14 14:03:09.000000', NULL, 1),
(6413507, 949704, 96751, '<td valign="top">Exquisite lighting.</td>', 'Exquisite lighting.', '2011-05-14 14:03:29.000000', NULL, 1),
(6413508, 950558, 96751, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2011-05-14 14:04:03.000000', NULL, 1),
(6413509, 949635, 96751, '<td valign="top">Interesting find.  Although the color surely lends itself to a vintage feel, I think there could be more contrast and tonal range to give more depth and visual interest.</td>', 'Interesting find.  Although the color surely lends itself to a vintage feel, I think there could be more contrast and tonal range to give more depth and visual interest.', '2011-05-14 14:05:03.000000', NULL, 1),
(6413510, 950709, 96751, '<td valign="top">Great find.  A couple of really wonderful abandonment images in this challenge.</td>', 'Great find.  A couple of really wonderful abandonment images in this challenge.', '2011-05-14 14:05:31.000000', NULL, 1),
(6413511, 949989, 96751, '<td valign="top">A pity the little girl isn''t looking into the camera.  It might have worked if she''d been intentionally (or more obviously) looking off camera, but this slight diversion makes it look like a missed shot.  On the other hand, the comparison of head sizes is just remarkable ;-)</td>', 'A pity the little girl isn''t looking into the camera.  It might have worked if she''d been intentionally (or more obviously) looking off camera, but this slight diversion makes it look like a missed shot.  On the other hand, the comparison of head sizes is just remarkable ;-)', '2011-05-14 14:07:06.000000', NULL, 1),
